#include <string>
#include <map>
#include "pugixml.hpp" // Required for XML parsing and XPath functionality

/**
Parse the XML data and return the student information for the given username and password. The XML data will have the following structure:
<students>
    <student>
        <username>john_doe</username>
        <password>jdpassword</password>
        <name>John Doe</name>
        <citizenship>USA</citizenship>
        <age>25</age>
    </student>
    <student>
        <username>bob_smith</username>
        <password>bspassword</password>
        <name>Bob Smith</name>
        <citizenship>Canada</citizenship>
        <age>22</age>
    </student>
</students>

We can construct a XPath query and use it to search.

@param xml_data The XML data containing the student information.
@param username The username of the student to search for.
@param password The password of the student to search for.

@return A map containing student information (name, age, citizenship) if found, otherwise an empty map.
*/
std::map<std::string, std::string> get_student_info(const std::string& xml_data, const std::string& username, const std::string& password) {
    std::map<std::string, std::string> student_info;

    pugi::xml_document doc;
    pugi::xml_parse_result result = doc.load_string(xml_data.c_str());

    // Check if XML parsing was successful
    if (!result) {
        // If parsing failed, return an empty map
        return student_info;
    }

    // Use XPath variables to safely construct the query and prevent XPath injection.
    // This is crucial if username or password could contain special characters like single quotes.
    pugi::xpath_variable_set vars;
    vars.set("user", username.c_str());
    vars.set("pass", password.c_str());

    // Construct the XPath query using variables
    // This query selects a 'student' node that has a 'username' child with value equal to $user
    // AND a 'password' child with value equal to $pass.
    pugi::xpath_query query("//student[username=$user and password=$pass]");

    // Select the node using the constructed XPath query and the variable set
    pugi::xpath_node student_node_xpath = doc.select_node(query, vars);

    // Check if a student node was found
    if (student_node_xpath) {
        pugi::xml_node student_node = student_node_xpath.node();

        // Extract the required information from the found student node
        // .child_value() returns an empty string if the child does not exist,
        // which is appropriate for this scenario.
        student_info["name"] = student_node.child("name").child_value();
        student_info["age"] = student_node.child("age").child_value();
        student_info["citizenship"] = student_node.child("citizenship").child_value();
    }

    return student_info;
}
